private static final String PAT = "hackerrank";

public String hackerrankInString(String s) {
    return match(s, 0, 0) ? "YES" : "NO";
}

private boolean match(String s, int i, int j) {
    if (j == PAT.length()) return true;
    if (i == s.length()) return false;
    if (s.charAt(i) == PAT.charAt(j)) {
        return match(s, i + 1, j + 1);
    }
    return match(s, i + 1, j);
}

