public String hackerrankInString(String s) {
    String pat = "hackerrank";
    int j = 0;
    for (int i = 0; i < s.length() && j < pat.length(); i++) {
        if (s.charAt(i) == pat.charAt(j)) {
            j++;
        }
    }
    return j == pat.length() ? "YES" : "NO";
}

